            "type": "custom",
            "tokenizer": "standard",
            "filter": ["standard", "shingle"]
          }
        },
        "filter": {
          "shingle": {
            "type": "shingle",
            "min_shingle_size": 2,
            "max_shingle_size": 3
          }
        }
      }
    }
  },
  "mappings": {
    "_doc": {
      "properties": {
        "message": {
          "type": "text",
          "fields": {
            "suggest": {
              "type": "text",
              "analyzer": "trigram"
            }
          }
        }
      }
    }
  }
}

